/// A reading's way to the level's word (`remember`).
const REMEMBERED: u16 = u16::MAX - 2;

/// Where a statement starts (the lean parser's `Mark`): its token, the comments, the tape's length, the levels and the
/// level's state, which a statement that fails is cut back to.
#[derive(Clone, Copy)]
struct Mark {
    i: usize,
    pend: usize,
    xi: usize,
    next_x: u32,
    w: usize,
    levels: usize,
    top: (u32, u32),
    last_end: u32,
    flags: u32,
    depth: u32,
    word: u16,
    asks: u64,
    refusing: u32,
    strings: usize,
}

/// The last bytes of the language's line terminators (`recover`'s `first`).
const TERMINATORS: &[u8] = &[0x0a, 0x0d];

#[allow(clippy::all, dead_code)]
impl<L: Layout> P<'_, L> {
    /// The statement's mark (the lean parser's `mark`).
    fn mark(&self) -> Mark {
        Mark { i: self.i, pend: self.pend, xi: self.xi, next_x: self.next_x, w: self.w.len(), levels: self.levels.len(), top: self.top, last_end: self.last_end, flags: self.flags, depth: self.depth, word: self.word, asks: self.asks, refusing: self.refusing, strings: self.strings }
    }

    /// Back at mark `m` (the lean parser's `reset`): its token and comments, the tape and the levels as they were.
    fn reset(&mut self, m: Mark) {
        self.i = m.i;
        self.pend = m.pend;
        self.xi = m.xi;
        self.next_x = m.next_x;
        self.w.plain_truncate(m.w);
        self.levels.truncate(m.levels);
        self.top = m.top;
        self.last_end = m.last_end;
        self.flags = m.flags;
        self.depth = m.depth;
        self.word = m.word;
        self.asks = m.asks;
        self.refusing = m.refusing;
        self.strings = m.strings;
        self.dead.retain(|&o| o != NONE && (o as usize) < m.w);
        self.taken = 0;
        let _ = self.arrive();
    }

    /// No node the statement made from `from` on holds a field a later token decides (`provisional`): one that does
    /// failed, as the lean parser's literal fails where no comparison follows a bare term.
    fn settled(&self, from: usize) -> R {
        if (from..self.w.len()).any(|i| matches!((self.w.plain_key(i) >> 10 & 0x3f) as u16, 63)) {
            return self.refuse();
        }
        Ok(())
    }

    /// A statement that failed, from mark `m` (the lean parser's `recover`): cut back to it, one ERROR leaf from its
    /// first token to the resume point, the comments inside it its text; then on from there. A limit refuses the file.
    fn recover(&mut self, m: Mark) -> R {
        if self.limited {
            return self.refuse();
        }
        let first = m.i;
        self.reset(m);
        let mut k = first + 1;
        while k < self.n {
            if (self.kind_at(k) == t::HASH_WORD && self.word_at(k) != w::HASH_INCLUDE_34 || self.word_at(k) == w::HASH_INCLUDE_34) || self.first_on_line(k) && self.word_at(k) == w::DOT_13 && self.kind_at(k + 1) == t::IDENTIFIER {
                break;
            }
            if self.word_at(k) == w::DOT_13 {
                k += 1;
                break;
            }
            k += 1;
        }
        let k = k.min(self.n);
        self.flush();
        let end = self.recs[k - 1].last + 1;
        let at = self.w.plain_leaf(ERROR, self.recs[first].start, end);
        self.set_made(at as u32);
        while self.xi < self.xs.len() && self.xs[self.xi].start < end {
            self.xi += 1;
        }
        self.pend = self.xi;
        self.next_x = self.xs.get(self.xi).map_or(u32::MAX, |x| x.start);
        self.i = k;
        self.last_end = end;
        self.pass_comments();
        self.arrive()
    }

    /// Whether token `j` is first on its line (the lean parser's `line_start`: only blanks before it back to a line's
    /// terminator or the file's start). Tier 1 leaves only blanks and line ends between records, so: no record before
    /// it, or a terminator among the bytes since the record before (the token before, or a comment after it), read a
    /// word at a time.
    fn first_on_line(&self, j: usize) -> bool {
        let at = self.recs[j].start as usize;
        let c = self.xs.partition_point(|x| (x.start as usize) < at);
        let before = [j.checked_sub(1).map(|i| self.recs[i].last), c.checked_sub(1).map(|i| self.xs[i].last)];
        let Some(last) = before.into_iter().flatten().max() else { return true };
        let mut i = last as usize + 1;
        while i < at {
            let n = (at - i).min(8);
            let mut w = [0u8; 8];
            w[..n].copy_from_slice(&self.src[i..i + n]);
            let x = u64::from_le_bytes(w);
            if TERMINATORS.iter().any(|&t| {
                let y = x ^ 0x0101_0101_0101_0101 * u64::from(t);
                y.wrapping_sub(0x0101_0101_0101_0101) & !y & 0x8080_8080_8080_8080 != 0
            }) {
                return true;
            }
            i += 8;
        }
        false
    }
}

/// An ERROR leaf's key: the tape's error code (`rerail_tape_format::CODE_ERROR`), of no kind or field.
const ERROR: u32 = (rerail_tape_format::CODE_ERROR as u32) << 16;

#[allow(clippy::all, dead_code)]
impl<L: Layout> P<'_, L> {
    /// `ending … K`: the node made last at this level is a `kind`.
    fn made_is(&self, kind: u16) -> bool {
        let at = self.top.1;
        at != NONE && self.w.plain_key(at as usize) & 0x3ff == u32::from(kind)
    }

    /// `relabel … inner G`: the node the node made last at this level, a wrap, holds first takes field `G`.
    fn relabel_inner(&mut self, field: u16) -> R {
        let at = self.top.1;
        if at == NONE || self.w.plain_size(at as usize) < 2 {
            return self.refuse();
        }
        let at = at as usize + 1;
        let k = self.w.plain_key(at);
        self.w.plain_set_key(at, k & !(0x3f << 10) | u32::from(field) << 10);
        Ok(())
    }

    /// `relabel F`: the node made last at this level takes field `F`.
    fn relabel_field(&mut self, field: u16) -> R {
        let at = self.top.1;
        if at == NONE {
            return self.refuse();
        }
        let k = self.w.plain_key(at as usize);
        self.w.plain_set_key(at as usize, k & !(0x3f << 10) | u32::from(field) << 10);
        Ok(())
    }

    /// `relabel … as M`: the node made last at this level a `kind` now.
    fn relabel_kind(&mut self, kind: u16) -> R {
        let at = self.top.1;
        if at == NONE {
            return self.refuse();
        }
        let k = self.w.plain_key(at as usize);
        self.w.plain_set_key(at as usize, k & !0x3ff | u32::from(kind));
        Ok(())
    }

    /// `drop`: the node made last at this level goes, the nodes inside it in its place; none is made last at this
    /// level until the next.
    ///
    /// As the machine's `drop` leaves its record of kind `DEAD` in the table (left out at `ACCEPT`), the node is held
    /// as dead in the node open (`dead`), so that a reading that reaches it refuses. A dead node in it goes to that
    /// node too.
    fn drop_made(&mut self) -> R {
        let at = self.top.1;
        let open = self.top.0;
        for o in &mut self.dead {
            if *o == at {
                *o = open;
            }
        }
        self.reread(Some(None), |_| None, |f| f)?;
        // Held once: a node open held dead again is held as before (a drop at each of a list's separators).
        if !self.dead.contains(&open) {
            self.dead.push(open);
        }
        self.set_made(NONE);
        Ok(())
    }

    /// The dead nodes (`drop`) in the node read again from `at` (`nodes`, as `reread` has them): one in a node the
    /// reading reaches, not one it keeps whole, refuses, as the machine's reading refuses the `DEAD` record it
    /// reaches (it names no such kind). Each other one is then in its node where the reading writes it.
    fn read_dead(&mut self, nodes: &[(u32, u32, u32, usize)], at: usize, root: Option<Option<u16>>, way: fn(u16) -> Option<Option<u16>>) -> R {
        let (mut to, mut reached) = (vec![NONE; nodes.len()], vec![false; nodes.len()]);
        let (mut next, mut kept) = (at as u32, 0);
        for (i, &(key, _, _, size)) in nodes.iter().enumerate() {
            let way = if i < kept || key >> 16 & 1 == 1 {
                None
            } else if i == 0 {
                match root {
                    Some(Some(u16::MAX)) => way((key & 0x3ff) as u16),
                    r => r,
                }
            } else {
                way((key & 0x3ff) as u16)
            };
            match way {
                None => kept = kept.max(i + size),
                Some(_) => reached[i] = true,
            }
            if way != Some(None) {
                to[i] = next;
                next += 1;
            }
        }
        for o in &mut self.dead {
            let j = (*o as usize).wrapping_sub(at);
            if j < nodes.len() {
                if reached[j] {
                    return self.refuse();
                }
                *o = to[j];
            }
        }
        Ok(())
    }
}

/// The tape of `src` from tier 1's records (each token's first and last bytes and code), finished by `finish` (the
/// image, or the columns, as the grammar's lean parser finishes), or the byte it was refused at.
pub fn parse<F: rerail_tape_format::Finish>(src: &[u8], lx: &crate::tier1::Lexed, finish: &mut F) -> Result<F::Out, u32> {
    // Where tier 1 sends the file to tree-sitter.
    if lx.refused {
        return Err(0);
    }
    let mut widths = Widths::guess(src.len());
    loop {
        // Nearly every file is parsed at the narrow widths, fixed in the parser's code, as the lean parser's.
        let at = if widths == Narrow::WIDTHS { parse_at(src, lx, Narrow, finish)? } else { parse_at(src, lx, widths, finish)? };
        match at {
            Ok(c) => return Ok(c),
            Err(rerail_tape_format::Redo(w)) => {
                if w == widths {
                    return Err(u32::MAX);
                }
                widths = w;
            }
        }
    }
}

/// `parse` at `layout`'s widths: the tape `finish` makes of the writer, or the widths to parse at again; or the byte
/// it was refused at.
fn parse_at<L: Layout, F: rerail_tape_format::Finish>(src: &[u8], lx: &crate::tier1::Lexed, layout: L, finish: &mut F) -> R<Result<F::Out, rerail_tape_format::Redo>> {
    let mut p = P::new(src, lx, layout)?;
    p.source_file()?;
    Ok(finish.finish(p.w))
}
